import React from "react";

export default function About() {
  return (
    <div className="about-page">

      {/* HERO */}
      <div className="about-hero">
        <h1>
          About <span>Me</span>
        </h1>

        <p className="tagline">
          IT Developer focused on building intelligent, user-first digital systems.
        </p>
      </div>

      {/* GRID */}
      <div className="about-grid">

        {/* LEFT */}
        <div className="card glass">

          {/* CHANGED TITLE */}
          <h2>My Developer Profile</h2>

          <p>
            I am an Information Technology student passionate about building
            real-world software solutions that are practical, scalable, and efficient.
            I enjoy exploring how systems work internally and transforming ideas into
            functional applications.
          </p>

          <p>
            I focus on structured thinking — breaking problems into smaller components,
            writing clean code, and improving through continuous project-based learning.
          </p>

        </div>

        {/* RIGHT STACK */}
        <div className="right-stack">

          {/* EDUCATION UPDATED */}
          <div className="card glass">
            <h2>🎓 Education</h2>

            <h4>B.Tech – Information Technology</h4>
            <p className="muted">Panimalar Engineering College</p>

            <div className="badge">2023 – 2027</div>

            {/* CGPA ADDED */}
            <p className="cgpa">
              CGPA: <span>8.81</span>
            </p>

            <p className="small">
              Focused on software development, system design, and hands-on project building.
            </p>
          </div>

          {/* SKILLS */}
          <div className="card glass">
            <h2>⚡ Core Skills</h2>

            <div className="chips">
              <span>Java</span>
              <span>React</span>
              <span>Spring Boot</span>
              <span>MySQL</span>
              <span>HTML</span>
              <span>CSS</span>
              <span>JavaScript</span>
              <span>UI/UX</span>
              <span>AI Basics</span>
            </div>
          </div>

        </div>
      </div>

      {/* HIGHLIGHTS */}
      <div className="highlights">
        <div>
          <h3>5+</h3>
          <p>Projects</p>
        </div>

        <div>
          <h3>10+</h3>
          <p>Technologies</p>
        </div>

        <div>
          <h3>2+</h3>
          <p>Domains</p>
        </div>
      </div>

      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 60px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0f172a, #050816);
          color: white;
        }

        .about-hero h1 {
          font-size: 46px;
        }

        .about-hero span {
          color: #38BDF8;
        }

        .tagline {
          color: #94a3b8;
          margin-bottom: 40px;
        }

        .about-grid {
          display: grid;
          grid-template-columns: 1.3fr 1fr;
          gap: 30px;
        }

        .card {
          padding: 22px;
          border-radius: 16px;
        }

        .glass {
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
          backdrop-filter: blur(10px);
        }

        h2 {
          color: #38BDF8;
          margin-bottom: 12px;
        }

        p {
          color: #cbd5e1;
          line-height: 1.7;
        }

        .muted {
          color: #94a3b8;
        }

        .small {
          font-size: 13px;
          margin-top: 10px;
        }

        /* CGPA STYLE */
        .cgpa {
          margin-top: 10px;
          font-weight: 600;
          color: #cbd5e1;
        }

        .cgpa span {
          color: #38BDF8;
          font-size: 18px;
        }

        .badge {
          display: inline-block;
          margin-top: 8px;
          padding: 3px 8px;
          font-size: 11px;
          border-radius: 8px;
          background: rgba(56,189,248,0.15);
          color: #38BDF8;
        }

        .chips {
          display: flex;
          flex-wrap: wrap;
          gap: 8px;
          margin-top: 10px;
        }

        .chips span {
          padding: 6px 10px;
          border-radius: 14px;
          font-size: 12px;
          background: rgba(255,255,255,0.06);
          border: 1px solid rgba(255,255,255,0.08);
        }

        .right-stack {
          display: flex;
          flex-direction: column;
          gap: 20px;
        }

        .highlights {
          margin-top: 50px;
          display: flex;
          justify-content: space-between;
          text-align: center;
        }

        .highlights h3 {
          color: #38BDF8;
          font-size: 28px;
        }

        .highlights p {
          color: #94a3b8;
        }

        @media (max-width: 900px) {
          .about-grid {
            grid-template-columns: 1fr;
          }

          .highlights {
            flex-direction: column;
            gap: 20px;
          }
        }

      `}</style>

    </div>
  );
}
